function terminalSpacing({ fresh = false } = {}) {
  if (state.automaticTipSpacing) {
    const root = state.workspaceMode === "cloud" ? state.cloud.speciesRoot
      : state.workspaceMode === "conflict" ? state.conflict.primaryDisplayRoot || state.conflict.nuclearRoot
      : state.root;
    const analysis = state.workspaceMode === "cloud" ? state.cloud : state;
    const visibleRows = state.workspaceMode === "conflict"
      ? PhyloRenderTreeOrder.visibleTipRows(state.conflict.prepared
        ? [state.conflict.prepared.nuclearRoot,state.conflict.prepared.plastidRoot]
        : [root,state.conflict.plastidRoot],{parallel:true}) : null;
    const tips = visibleRows ? visibleRows.tips : root ? descendantTipNodes(root) : [];
    const size = Number($("tip-font-size").value);
    const inkHeight = state.workspaceMode === "conflict"
      ? tips.length ? Math.max(...tips.map(tip => conflictTipTextMetrics(tip.label).height)) : size
      : maximumTipInkHeight(tips, analysis, size);
    const minimum = inkHeight + automaticTipGap(visibleRows?.rowCount ?? tips.length, size);
    const layout = state.currentLayoutInfo;
    if (!fresh && Number.isFinite(layout?.tipSpacing)) {
      return layout.tipSpacingRoot === root && layout.baseTipSpacing === minimum ? layout.tipSpacing
        : Number($("tip-spacing").value) || minimum;
    }
    return minimum;
  }
  return state.tipSpacingEm === null
    ? Number($("tip-spacing").value)
    : state.tipSpacingEm * Number($("tip-font-size").value);
}

