  const splitText = split.panels === 2
    ? "; two-panel export isolates a major monophyletic clade"
    : "; single-panel export (no split required)";
  status.textContent = `Print size ${physical.width_mm.toFixed(1)} × ${physical.height_mm.toFixed(1)} mm (W/H ${aspect.toFixed(2)})${expanded}; max width ${physical.maximum_width_mm} mm${physical.width_limited_to_maximum ? " (at limit)" : ""}; PNG ${pngWidth} × ${pngHeight} px (${physical.effective_dpi.toFixed(0)} DPI)${limited}${splitText}`;
  status.dataset.canvasWidth = String(width);
  status.dataset.canvasHeight = String(height);
  status.dataset.aspectRatio = aspect.toFixed(4);
  status.dataset.pngWidth = String(pngWidth);
