function tipDisplaySource(label) {
  const raw = String(label || "");
  return currentTipLabelOverrides().get(raw) || baseTipDisplayLabel(raw);
}

function formattedTipLabel(label) {
  const original = tipDisplaySource(label);
  if (!$("tip-normalize-ranks")?.checked || !globalThis.PhyloRenderTaxonRanks) {
    return { text: original, changes: [] };
  }
  return globalThis.PhyloRenderTaxonRanks.normalizeWithReport(original);
}

function displayTipLabel(label) {
  return formattedTipLabel(label).text;
}

function scientificNameSegmentsFromAnalysis(...args) { return PhyloRenderNameFormat.scientificNameSegmentsFromAnalysis(...args); }

