function scientificNameSegments(rawLabel, analysis = state) {
  const text = displayTipLabel(rawLabel);
  return scientificNameSegmentsFromAnalysis(
    text,
    analysis.taxonNameMatches.get(text),
    analysis.taxonNameParses.get(text),
  );
}

function appendTipLabelContent(element, rawLabel, analysis = state) {
  const formatted = formattedTipLabel(rawLabel);
  const text = formatted.text;
  element.setAttribute("data-original-tip-label", String(rawLabel || ""));
  element.setAttribute("data-display-tip-label", text);
  element.setAttribute("data-tip-name-customized", currentTipLabelOverrides().has(String(rawLabel || "")) ? "true" : "false");
  element.setAttribute("data-rank-change-count", formatted.changes.length);
  if (formatted.changes.length) {
    element.setAttribute("data-rank-changes", formatted.changes.map(change => `${change.original}→${change.standard}`).join("|"));
  }
  const mode = $("tip-italic-mode").value;
  if (mode !== "auto") {
    element.textContent = text;
    return;
  }
  const segments = scientificNameSegments(rawLabel, analysis);
  segments.forEach(segment => {
    element.append(svgEl("tspan", segment.italic ? { class: "scientific-name-part" } : {}, segment.text));
  });
  element.setAttribute("data-italic-segments", segments.filter(segment => segment.italic).map(segment => segment.text).join("|"));
  element.setAttribute("data-name-engine", analysis.taxonNameEngine);
}

