function applyTypographySettings(svg) {
  syncCladeFontSize();
  svg.style.setProperty("--figure-system-sans", figureSystemSansFamily());
  const timeFonts = timeTypographySettings();
  for (const type of ["period", "epoch", "legend", "axis", "unit", "key"]) {
    svg.style.setProperty(`--time-${type}-font-size`, `${timeFonts[type]}px`);
  }
  ["support", "clade", "scale"].forEach(type => {
    svg.style.setProperty(`--${type}-font-family`, $(`${type}-font-family`).value);
    svg.style.setProperty(`--${type}-font-weight`, $(`${type}-font-bold`).checked ? "700" : "400");
    svg.style.setProperty(`--${type}-font-style`, $(`${type}-font-italic`).checked ? "italic" : "normal");
    if (type !== "clade") svg.style.setProperty(`--${type}-color`, $(`${type}-font-color`).value);
  });
  svg.style.setProperty("--tip-font-family", $("tip-font-family").value);
  svg.style.setProperty("--tip-font-weight", $("tip-font-bold").checked ? "700" : "400");
  svg.style.setProperty("--tip-font-style", $("tip-italic-mode").value === "all" ? "italic" : "normal");
  svg.style.setProperty("--tip-color", $("tip-font-color").value);
  svg.style.setProperty("--tip-font-size", `${$("tip-font-size").value}px`);
  svg.style.setProperty("--clade-font-size", `${$("clade-font-size").value}px`);
  svg.style.setProperty("--scale-font-size", `${$("scale-font-size").value}px`);
  svg.style.setProperty("--branch-width", `${$("branch-width").value}px`);
}

function customFontNames(fontStack) {
  return [...String(fontStack || "").matchAll(/["']([^"']+)["']/g)]
    .map(match => match[1])
    .filter(name => name.startsWith("PhyloRender ") || name === "Noto Sans SC Variable");
}

function figureTextSample() {
  const roots = state.workspaceMode === "cloud" ? [state.cloud.speciesRoot]
    : state.workspaceMode === "conflict" ? [state.conflict.primaryDisplayRoot || state.conflict.nuclearRoot, state.conflict.plastidRoot]
    : [state.root];
  const labels = roots.filter(Boolean).flatMap(root => descendantTipNodes(root).map(node => displayTipLabel(node.label)));
  const extra = state.workspaceMode === "conflict"
    ? [$("conflict-primary-title")?.value, $("conflict-secondary-title")?.value,
        ...(state.conflict.prepared?.groupColors?.groups || []).map(g => g.name)]
    : activeCladeState().cladeNames.values();
  const text = [...labels, ...extra, "0123456789.-—/()[]% Mya"].join(" ");
  return [...new Set([...text])].join("").slice(0, 12000) || "PhyloRender 0123456789";
}

function figureFontLoadPlan() {
  const plan = [];
  const addStack = (stack, weight, styles) => {
    customFontNames(stack).forEach(family => {
      const usableStyles = family === "Noto Sans SC Variable" ? ["normal"] : styles;
      usableStyles.forEach(style => plan.push({ family, weight, style }));
    });
  };
  const add = (controlId, weight, styles) => addStack($(controlId)?.value || "", weight, styles);
  add("tip-font-family", $("tip-font-bold")?.checked ? 700 : 400,
    $("tip-italic-mode")?.value === "none" ? ["normal"] : ["normal", "italic"]);
  add("support-font-family", $("support-font-bold")?.checked ? 700 : 400,
    [$("support-font-italic")?.checked ? "italic" : "normal"]);
  add("clade-font-family", $("clade-font-bold")?.checked ? 700 : 400,
    [$("clade-font-italic")?.checked ? "italic" : "normal"]);
  activeCladeState().cladeNameSegments.forEach(segments => segments.forEach(segment => {
    if (!segment.family) return;
    const style = cladeSegmentEffectiveStyle(segment);
    addStack(style.family, style.bold ? 700 : 400, [style.italic ? "italic" : "normal"]);
  }));
  add("scale-font-family", $("scale-font-bold")?.checked ? 700 : 400,
    [$("scale-font-italic")?.checked ? "italic" : "normal"]);
  if (["time", "cloud", "conflict"].includes(state.workspaceMode)) {
    [400, 700].forEach(weight => addStack(figureSystemSansFamily(), weight, ["normal", "italic"]));
  }
  const unique = new Map(plan.map(item => [`${item.family}|${item.weight}|${item.style}`, item]));
  return [...unique.values()];
}

function figureFontLoadKey() {
  return JSON.stringify({ plan: figureFontLoadPlan(), system: figureSystemFontFamilies(), sample: figureTextSample() });
}

const systemFontAvailabilityCache = new Map();
let systemArialFallback = false;

function figureSystemSansFamily() {
  return systemArialFallback ? FIGURE_FONT_FAMILIES.arimo : "Arial, sans-serif";
}

function usesArialFont(stack) {
  return /(?:^|,)\s*["']?Arial["']?\s*(?:,|$)/i.test(String(stack || ""));
}

function applyArialFallback() {
  systemArialFallback = true;
  ["tip-font-family", "support-font-family", "clade-font-family", "scale-font-family"].forEach(id => {
    if (usesArialFont($(id)?.value)) $(id).value = FIGURE_FONT_FAMILIES.arimo;
  });
  activeCladeState().cladeNameSegments.forEach(segments => segments.forEach(segment => {
    if (usesArialFont(segment.family)) segment.family = FIGURE_FONT_FAMILIES.arimo;
  }));
  state.pendingCladeNameSegments.forEach(segment => {
    if (usesArialFont(segment.family)) segment.family = FIGURE_FONT_FAMILIES.arimo;
  });
  document.querySelectorAll("#clade-segment-list select").forEach(select => {
    if (usesArialFont(select.value)) select.value = FIGURE_FONT_FAMILIES.arimo;
  });
  const notice = $("figure-font-notice");
  if (notice) {
    notice.hidden = false;
    notice.textContent = "Arial is not installed in this rendering environment; Arimo (not Arial) has been substituted explicitly for figure output.";
  }
}

function figureSystemFontFamilies() {
  const stacks = ["tip-font-family", "support-font-family", "clade-font-family", "scale-font-family"]
    .map(id => $(id)?.value || "");
  activeCladeState().cladeNameSegments.forEach(segments => segments.forEach(segment => stacks.push(segment.family || "")));
  // These workspaces also use Arial for their fixed figure keys or headings.
  const needsArial = (!systemArialFallback && ["time", "cloud", "conflict"].includes(state.workspaceMode))
    || stacks.some(usesArialFont);
  return needsArial ? ["Arial"] : [];
}

async function ensureSystemFigureFontsReady() {
  // Probe the shared system stack even when this configuration already names
  // embedded fonts, so a fresh MCP page and a previously used GUI agree.
  for (const family of ["Arial"]) {
    if (!systemFontAvailabilityCache.has(family)) {
      // A local FontFace probe must resolve a real installed font. fonts.check()
      // alone can return true after a CSS fallback and cannot prove availability.
      const available = typeof FontFace === "function"
        ? new FontFace("PhyloRender System Font Probe", `local("${family}")`).load()
          .then(() => true, () => false)
        : Promise.resolve(false);
      systemFontAvailabilityCache.set(family, available);
    }
    if (!await systemFontAvailabilityCache.get(family)) {
      applyArialFallback();
    }
  }
}

async function ensureFigureFontsReady() {
  await ensureSystemFigureFontsReady();
  if (!document.fonts?.load) return figureFontLoadKey();
  const key = figureFontLoadKey();
  if (readyFigureFontKeys.has(key)) return key;
  const sample = figureTextSample();
  await Promise.all(figureFontLoadPlan().map(({ family, weight, style }) =>
    document.fonts.load(`${style} ${weight} 16px "${family}"`, sample)));
  await document.fonts.ready;
  readyFigureFontKeys.add(key);
  return key;
}

function scheduleFigureFontRerender() {
  const key = figureFontLoadKey();
  if (readyFigureFontKeys.has(key)) return;
  const requestToken = ++figureFontRequestToken;
  ensureFigureFontsReady().then(loadedKey => {
    if (requestToken !== figureFontRequestToken || loadedKey !== figureFontLoadKey()
      || lastRenderedFigureFontKey === loadedKey || activeTreeLoad) return;
    renderTree({ fontReady: true });
  }).catch(error => showMessage(`Figure font verification failed: ${error.message}`, true));
}

window.PhyloRenderEnsureFonts = ensureFigureFontsReady;

function resetTypography() {
  Object.entries(TYPOGRAPHY_DEFAULTS).forEach(([id, value]) => {
    const control = $(id);
    if (typeof value === "boolean") control.checked = value;
    else control.value = value;
    const output = $(`${id}-value`);
    if (output) output.textContent = `${value} px`;
  });
  const modeDefaults = figureUnits.legacyOptions(PhyloRenderContract.defaults(state.workspaceMode));
  $("tip-font-size").value = String(Math.round((modeDefaults.typography?.tips?.size_pt || 15) * 4 / 3));
  if (modeDefaults.typography?.tips?.color) $("tip-font-color").value = modeDefaults.typography.tips.color;
  if (modeDefaults.typography?.support?.size_pt) $("support-size").value = String(Math.round(modeDefaults.typography.support.size_pt * 4 / 3));
  if ($("support-size-auto")) $("support-size-auto").checked = true;
  $("clade-font-auto").checked = true;
  $("clade-font-size").value = cladePresentationDefaults(state.workspaceMode).size;
  applyArialFallback();
  refreshNumericControls();
  sampleNameOperations().invalidateRanks();
  void refreshTaxonNameRecognition();
  requestSettingsRender();
}

