async function readTreeFile(file, collection = false) {
  const maximum = collection ? 120000000 : 12000000;
  if (file.size > maximum) throw Object.assign(new Error(`Input file exceeds the ${collection ? 120 : 12} MB safety limit; rejected without partial reading.`), {code:"TREE_INPUT_LIMIT"});
  checkScienceCancellation();
  const text = await file.text();
  checkScienceCancellation();
  return text;
}

