function nodeLabelInkRect(element, fallback) {
  const context = nodeLabelInkRect.context ||= document.createElement("canvas").getContext("2d");
  if (!context) return fallback;
  const style = getComputedStyle(element);
  context.font = `${style.fontStyle} ${style.fontWeight} ${element.getAttribute("font-size")}px ${style.fontFamily}`;
  const metrics = context.measureText(element.textContent);
  const width = metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight;
  const height = metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent;
  if (!(width > 0 && height > 0)) return fallback;
  return { x: Number(element.getAttribute("x")) - metrics.actualBoundingBoxLeft,
    y: Number(element.getAttribute("y")) - metrics.actualBoundingBoxAscent, width, height };
}


