function appendNodeLabelArrow(leaderGroup, node, rect, plan, id, kind) {
  if (!plan?.points || plan.length <= .25) return false;
  const [origin, target] = plan.points;
  // Draw from the nearest text edge toward the owning node, so both the shaft
  // direction and the arrow tip encode the true node relationship.
  const shaftAttributes = {
    x1: target.x,
    y1: target.y,
    x2: origin.x,
    y2: origin.y,
  };
  const baseClass = kind === "time" ? "time-age" : "support";
  if (plan.crossings > 0) {
    leaderGroup.prepend(svgEl("line", {
      class: `${baseClass}-leader-halo`,
      "data-leader-halo-id": id,
      "data-bridged-crossings": plan.crossings,
      "data-straight-leader": "true",
      ...shaftAttributes,
    }));
  }
  leaderGroup.append(svgEl("line", {
    class: `${baseClass}-leader node-label-arrow`,
    ...(kind === "time" ? { "data-time-leader-id": node.id } : {}),
    "data-leader-id": id,
    "data-arrow-label-id": id,
    "data-arrow-node-id": node.id,
    "data-arrow-node-x": origin.x,
    "data-arrow-node-y": origin.y,
    "data-arrow-points-to-node": "true",
    "data-branch-crossings": plan.crossings,
    "data-node-circle-crossings": plan.nodeHits || 0,
    "data-crossings-bridged": String(plan.crossings > 0),
    "data-leader-length": plan.length.toFixed(3),
    "data-axis-angle-degrees": plan.axisAngle.toFixed(3),
    "data-angle-reference": "horizontal",
    "data-preferred-axis-angle-degrees": PREFERRED_NODE_ARROW_AXIS_ANGLE,
    "data-minimum-leader-length": MIN_NODE_ARROW_LENGTH,
    "data-sufficiently-angled": String(plan.sufficientlyAngled),
    "data-straight-leader": "true",
    "data-line-style": "dashed",
    ...shaftAttributes,
  }));
  const headPath = nodeArrowHeadPath(origin, target);
  if (headPath) {
    leaderGroup.append(svgEl("path", {
      class: `${baseClass}-arrowhead node-label-arrowhead`,
      d: headPath,
      "data-arrowhead-label-id": id,
      "data-arrowhead-node-id": node.id,
      "data-arrow-node-x": origin.x,
      "data-arrow-node-y": origin.y,
      "data-arrow-points-to-node": "true",
      "data-arrowhead-length": NODE_ARROW_HEAD_LENGTH,
      "data-arrowhead-half-width": NODE_ARROW_HEAD_HALF_WIDTH,
    }));
  }
  return true;
}

const MAX_TIME_AGE_EDGE_DISTANCE = PhyloRenderLabelGeometry.MAX_TIME_AGE_EDGE_DISTANCE;
const MAX_TIME_AGE_LEADER_LENGTH = PhyloRenderLabelGeometry.MAX_TIME_AGE_LEADER_LENGTH;
const MIN_TIME_AGE_LEADER_TRIGGER_DISTANCE = PhyloRenderLabelGeometry.MIN_TIME_AGE_LEADER_TRIGGER_DISTANCE;

function timeAgeMaximumEdgeDistance(...args) { return PhyloRenderLabelGeometry.timeAgeMaximumEdgeDistance(...args); }
function timeAgeLeaderTriggerDistance(...args) { return PhyloRenderLabelGeometry.timeAgeLeaderTriggerDistance(...args); }
function timeAgeCandidatePlacements(...args) { return PhyloRenderLabelGeometry.timeAgeCandidatePlacements(...args); }
function readableFontSizes(...args) { return PhyloRenderLabelGeometry.readableFontSizes(...args); }

function syncAutomaticNodeSize(geometry = {}) {
  if ($("support-size-auto")?.checked) {
    const planned = PhyloRenderContract.planAutomaticNodeSize({ ...geometry, automatic: true,
      tipSizePx: geometry.tipSizePx || Number($("tip-font-size").value) || 20,
      minimumSizePx: Math.max(9, Number($("support-min-size").value)), currentSizePx: Number($("support-size").value) });
    syncNumericControl(NUMERIC_SETTING_CONTROLS.find(c => c.rangeId === "support-size"), planned.sizePx, { render: false });
  }
  return nodeLabelFontSettings();
}

function nodeLabelFontSettings() {
  const minimum = Math.max(9, Number($("support-min-size").value));
  const preferred = Math.max(minimum, Number($("support-size").value));
  // A lower preferred value must never silently lower the user's hard floor.
  if (Number($("support-size").value) < minimum) {
    $("support-size").value = String(preferred);
    refreshNumericControls();
  }
  return { preferred, minimum };
}

const supportValues = PhyloRenderSupportValues.create(PhyloRenderSupportScale);
function mainSupportScales(values = state.mainSupportValues, declared = $("support-scale").value) { return supportValues.profile(values.values(), declared); }
function isBelowSupportThreshold(value, threshold, scales) { return supportValues.below(value, threshold, scales); }

function supportPrecisionSetting() {
  const setting = $("support-decimals").value;
  return setting === "original" || setting === "auto" ? setting : Number(setting);
}

function supportComponentsAtDisplayPrecision(value) {
  const setting = supportPrecisionSetting();
  return String(value).split("/").map(part => {
    const numeric = Number(part);
    if (!Number.isFinite(numeric) || setting === "original") return numeric;
    const digits = setting === "auto" ? (numeric > 1 ? 0 : 2) : setting;
    return Number(numeric.toFixed(digits));
  });
}

function isFullSupport(value, scales) {
  return supportValues.full(value, scales, supportPrecisionSetting());
}

function formatSupportValue(value, threshold = 0, scales) {
  return supportValues.format(value, threshold, supportPrecisionSetting(), scales);
}

function normalizeTipKey(...args) { return PhyloRenderSampleIdentity.normalizeTipKey(...args); }

function tipRolePrefixInfo(...args) { return PhyloRenderSampleIdentity.tipRolePrefixInfo(...args); }

function buildTipKeyAlignment(...args) { return PhyloRenderSampleIdentity.buildTipKeyAlignment(...args); }

function resolvedTipKey(...args) { return PhyloRenderSampleIdentity.resolvedTipKey(...args); }

function canonicalSplitKey(...args) { return PhyloRenderSampleIdentity.canonicalSplitKey(...args); }

function allNormalizedTips(...args) { return PhyloRenderSampleIdentity.allNormalizedTips(...args); }

function treeTimeDiagnostics(...args) { return PhyloRenderTreeGeometry.treeTimeDiagnostics(...args); }

function nodeValueForExtraction(node, extraction) {
  if (extraction === "labels" || extraction === "auto-support") return supportFromNode(node);
  if (extraction.startsWith("field:")) return numericFieldsFromNode(node).get(extraction.slice(6))?.value ?? null;
  return null;
}

function isNumericDisplayValue(value) {
  return String(value ?? "").split(/[\/–—·,]/).map(part => part.trim()).filter(Boolean).every(part => NUMERIC_TOKEN_RE.test(part));
}

function buildNodeValueIndex(root, extraction = "auto-support", tipKeyMap = null) {
  const allTips = allNormalizedTips(root, tipKeyMap);
  const values = new Map();
  function visit(node, isRoot = false) {
    if (!node.children.length) return { tips: [resolvedTipKey(node.label, tipKeyMap)], height: 0 };
    const childResults = node.children.map(child => visit(child));
    const tips = childResults.flatMap(result => result.tips);
    const height = Math.max(...node.children.map((child, index) => (child.length ?? 0) + childResults[index].height));
    if (!isRoot) {
      const key = canonicalSplitKey(tips, allTips);
      const value = extraction === "ages" ? height : nodeValueForExtraction(node, extraction);
      const numericValue = extraction === "ages"
        ? Number.isFinite(Number(value))
        : isNumericDisplayValue(value);
      if (key && value !== null && value !== "" && numericValue) values.set(key, value);
    }
    return { tips, height };
  }
  visit(root, true);
  return values;
}

function collectDisplaySplitKeys(root, policy = "auxiliary") {
  const allTips = allNormalizedTips(root, null, policy);
  const keys = new Set();
  function visit(node, isRoot = false) {
    if (!node.children.length) return [PhyloRenderSampleIdentity.tipIdentityKey(node.label, policy)];
    const tips = node.children.flatMap(child => visit(child));
    if (!isRoot) {
      const key = canonicalSplitKey(tips, allTips);
      if (key) keys.add(key);
    }
    return tips;
  }
  visit(root, true);
  return keys;
}

function formatOtherValue(source, value) {
  const digits = Math.max(0, Math.min(6, Number(source.digits ?? 2)));
  return String(value).split(/([\/–—·,])/).map(part => {
    const numeric = Number(part.trim());
    return part.trim() !== "" && Number.isFinite(numeric) ? numeric.toFixed(digits) : part;
  }).join("");
}

function buildMainSupportIndex(root, workspaceMode = state.workspaceMode) {
  if (workspaceMode !== "time") return buildNodeValueIndex(root, "auto-support");
  const supportKeys = [
    "posterior", "prob", "probability", "support", "bootstrap", "b",
    "pp1", "ufboot", "sh_alrt", "aBayes", "localpp",
  ];
  const catalog = discoverNodeNumericFields(root);
  const field = supportKeys
    .map(key => catalog.find(item => item.key.toLowerCase() === key.toLowerCase()))
    .find(Boolean);
  return field ? buildNodeValueIndex(root, `field:${field.key}`) : new Map();
}

function countDescendantTips(...args) { return PhyloRenderTreeGeometry.countDescendantTips(...args); }

function rootAdjacentSupportlessNodeIds(...args) { return PhyloRenderTreeGeometry.rootAdjacentSupportlessNodeIds(...args); }

function annotateNodeData(root) {
  const allTips = allNormalizedTips(root);
  const supportSources = state.workspaceMode === "time" ? [] : state.nodeDataSources.filter(source => source.kind === "support");
  const otherSources = state.nodeDataSources.filter(source => source.kind === "other");
  const hasMainSupport = state.workspaceMode !== "time" && state.mainSupportValues.size > 0;
  const mainScales = hasMainSupport ? mainSupportScales() : [];
  const sourceScales = new Map(supportSources.map(source => [source, mainSupportScales(source.values, source.scale || "auto")]));
  const supportlessRootNodes = rootAdjacentSupportlessNodeIds(root);

  function visit(node, isRoot = false) {
    if (!node.children.length) return [normalizeTipKey(node.label)];
    const tips = node.children.flatMap(child => visit(child));
    const key = isRoot ? null : canonicalSplitKey(tips, allTips);
    const suppressSupport = supportlessRootNodes.has(node.id);
    const supportEntries = [];
    if (!suppressSupport && hasMainSupport) {
      const value = key ? state.mainSupportValues.get(key) : undefined;
      supportEntries.push({ source: null, value, scales: mainScales, present: value !== undefined });
    }
    if (!suppressSupport) {
      supportSources.forEach(source => {
        const value = key ? source.values.get(key) : undefined;
        supportEntries.push({ source, value, scales: sourceScales.get(source), present: value !== undefined });
      });
    }
    let supportText = null;
    // Missing in every source is not a low support value. In particular, an
    // old root can become a unary display node after legitimate rerooting.
    // Keep its path lengths but never invent a –/– label or leader for it.
    if (node.children.length > 1 && supportEntries.some(entry => entry.present)) {
      const threshold = Number($("support-threshold").value);
      supportText = supportEntries.map(entry => entry.present ? formatSupportValue(entry.value, threshold, entry.scales) : "–").join("/");
    }
    const otherValues = otherSources.flatMap(source => {
      const value = key ? source.values.get(key) : undefined;
      return value === undefined ? [] : [formatOtherValue(source, value)];
    });
    node.nodeData = {
      key,
      supportEntries,
      supportText,
      otherText: otherValues.length ? otherValues.join(" · ") : null,
      allSupportsFull: supportEntries.length > 0
        && supportEntries.every(entry => entry.present)
        && supportEntries.every(entry => isFullSupport(entry.value, entry.scales)),
    };
    return tips;
  }
  visit(root, true);
}

function composeNodeAnnotation(node, leadingText = null) {
  const data = node.nodeData || {};
  const presentSupportEntries = (data.supportEntries || []).filter(entry => entry.present);
  const hasSupportValues = presentSupportEntries.length > 0;
  let supportText = data.supportText || null;
  let fullMarker = false;
  if (data.allSupportsFull) {
    const style = $("full-support-style").value;
    if (style === "branch") {
      supportText = null;
    } else if (style === "circle") {
      fullMarker = true;
      supportText = null;
    } else if (style === "star") {
      supportText = "*";
    } else if (style === "hide") {
      supportText = null;
    }
  }
  const pieces = [leadingText, supportText, data.otherText].filter(value => value !== null && value !== "");
  return {
    text: pieces.length ? pieces.join(" | ") : null,
    fullMarker,
    supportMarkerKind: hasSupportValues
      ? (data.allSupportsFull && fullMarker ? "full" : (!data.allSupportsFull ? "partial" : null))
      : null,
    supportValues: presentSupportEntries.map(entry => entry.value).join("/"),
    hasContent: pieces.length > 0 || fullMarker,
  };
}

function composeTimeNodeAnnotation(node, leadingText = null) {
  const otherText = node.nodeData?.otherText || null;
  const pieces = [leadingText, otherText].filter(value => value !== null && value !== "");
  return {
    text: pieces.length ? pieces.join(" | ") : null,
    fullMarker: false,
    supportMarkerKind: null,
    supportValues: "",
    hasContent: pieces.length > 0,
  };
}

function fullSupportBranchAttributes(node, baseClass) {
  const full = $("full-support-style").value === "branch" && Boolean(node?.nodeData?.allSupportsFull);
  return {
    class: `${baseClass}${full ? " full-support-branch" : ""}`,
    ...(full ? { "data-support-state": "full", "data-support-branch": "true" } : {}),
  };
}

function appendSupportNodeMarker(group, node, annotation) {
  if (!annotation.supportMarkerKind) return;
  const isFull = annotation.supportMarkerKind === "full";
  group.append(svgEl("circle", {
    class: `support-node-marker support-node-marker-${annotation.supportMarkerKind}${isFull ? " full-support-marker" : " partial-support-marker"}`,
    cx: node.x,
    cy: node.y,
    r: Number($("node-radius")?.value) || 5,
    "data-support": annotation.supportValues,
    "data-support-state": annotation.supportMarkerKind,
    "data-edge-id": node.incomingEdgeId || node.id,
  }));
}

function inferNodeDataName(fileName, kind, extraction) {
  const base = fileName.replace(/\.[^.]+$/, "");
  if (kind === "support") {
    if (/raxml|bootstrap|boot/i.test(base)) return "Bootstrap";
    if (/mrbayes|bayes|con\.tre/i.test(base)) return "Posterior probability";
    return base;
  }
  if (extraction === "ages" || /treepl|time|dated|chronogram/i.test(base)) return "Node age";
  return base;
}

function matchedNodeValueCount(source) {
  if (!state.root) return 0;
  const mainKeys = collectDisplaySplitKeys(state.root);
  let count = 0;
  source.values.forEach((value, key) => { if (mainKeys.has(key)) count++; });
  return count;
}

function extractionDisplayLabel(source) {
  if (source.extraction === "ages") return "Node age from ultrametric branch lengths";
  if (source.extraction === "auto-support") return "Auto-detected branch support";
  if (source.extraction.startsWith("field:")) {
    const key = source.extraction.slice(6);
    return source.fieldCatalog.find(field => field.key === key)?.label || annotationFieldLabel(key);
  }
  return source.extraction;
}

function makeNodeDataItem(source) {
  const item = document.createElement("div");
  item.className = `node-data-item ${source.kind}`;
  const dot = document.createElement("span");
  dot.className = "node-data-dot";
  const content = document.createElement("div");
  content.className = "node-data-content";
  const name = document.createElement("input");
  name.className = "node-data-name";
  name.value = source.name;
  name.addEventListener("change", () => {
    source.name = name.value.trim() || inferNodeDataName(source.fileName, source.kind, source.extraction);
    renderNodeDataLists();
  });
  const meta = document.createElement("div");
  meta.className = "node-data-meta";
  const matched = matchedNodeValueCount(source);
  const rootMode = source.kind === "support" ? " · unrooted bipartitions" : "";
  const alignment = source.tipAlignment?.alignedCount
    ? ` · auto-aligned ${source.tipAlignment.alignedCount} taxon names`
    : "";
  meta.textContent = `${source.fileName} · ${extractionDisplayLabel(source)} · matched ${matched}/${source.values.size} nodes${rootMode}${alignment}`;
  name.setAttribute("aria-label", `Display name for ${source.name}`);
  const heading = document.createElement("strong");
  heading.className = "node-data-heading";
  heading.textContent = source.name;
  const file = document.createElement("div");
  file.className = "node-data-file";
  file.textContent = source.fileName;
  file.title = source.fileName;
  const match = document.createElement("div");
  match.className = "node-data-match";
  match.textContent = `Matched ${matched} / ${source.values.size} nodes`;
  content.append(heading, file, match);

  const settings = document.createElement("div");
  settings.className = "node-data-settings";
  const modeLabel = document.createElement("span");
  modeLabel.textContent = "Source field";
  const mode = document.createElement("select");
  if (source.kind === "support" && source.autoSupportCount > 0) {
    mode.append(new Option(`Auto-detected support (${source.autoSupportCount})`, "auto-support"));
  }
  source.fieldCatalog.forEach(field => {
    if (source.kind === "support" && !field.scalar && field.key !== "label") return;
    mode.append(new Option(`${field.label} (${field.count})`, `field:${field.key}`));
  });
  if (source.kind === "other" && source.ageEligible) mode.append(new Option("Node age from ultrametric branch lengths", "ages"));
  mode.value = source.extraction;
  mode.setAttribute("aria-label", `Source field for ${source.name}`);
  mode.addEventListener("change", () => {
    const next=buildNodeValueIndex(source.parsedRoot,mode.value,source.tipKeyMap);
    try { if(source.kind==="support") mainSupportScales(next,source.scale||"auto"); }
    catch(error){mode.value=source.extraction;showMessage(error.message,true);return;}
    source.extraction = mode.value;
    source.values = next;
    state.manualLabels.clear();
    renderTree();
    renderNodeDataLists();
  });
  settings.append(modeLabel, mode);
  if(source.kind==="support") PhyloRenderSupportUnits.append({parent:settings,createElement:tag=>document.createElement(tag),name:source.name,value:source.scale||"auto",
    validate:value=>mainSupportScales(source.values,value),commit:value=>{source.scale=value;requestSettingsRender();},onError:error=>showMessage(error.message,true)});
  if (source.kind === "other") {
    const digitsLabel = document.createElement("span");
    digitsLabel.textContent = "Decimals";
    const digits = document.createElement("input");
    digits.type = "number";
    digits.min = "0";
    digits.max = "6";
    digits.step = "1";
    digits.value = source.digits;
    digits.addEventListener("change", () => {
      source.digits = Math.max(0, Math.min(6, Number(digits.value) || 0));
      digits.value = source.digits;
      state.manualLabels.clear();
      renderTree();
    });
    settings.append(digitsLabel, digits);
    PhyloRenderNumericControls.compactBoundedNumber(document, digits, "");
  }
  const disclosure = document.createElement("details");
  disclosure.className = "source-options optional-settings";
  const summary = document.createElement("summary");
  summary.textContent = "Source details & field extraction";
  disclosure.append(summary, name, meta, settings);
  content.append(disclosure);

  const action = document.createElement("button");
  action.className = "node-data-remove";
  action.type = "button";
  action.textContent = "×";
  action.setAttribute("aria-label", `Remove ${source.name}`);
  action.addEventListener("click", () => {
    state.nodeDataSources = state.nodeDataSources.filter(itemSource => itemSource.id !== source.id);
    state.manualLabels.clear();
    renderTree();
    renderNodeDataLists();
  });
  item.append(dot, content, action);
  return item;
}

function renderNodeDataLists() {
  const supportList = $("support-data-list"), otherList = $("other-data-list");
  supportList.replaceChildren();
  otherList.replaceChildren();
  state.nodeDataSources.forEach(source => {
    (source.kind === "support" ? supportList : otherList).append(makeNodeDataItem(source));
  });
  const supportCount = state.nodeDataSources.filter(source => source.kind === "support").length;
  const otherCount = state.nodeDataSources.filter(source => source.kind === "other").length;
  if (otherCount && $("other-data-disclosure")) $("other-data-disclosure").open = true;
  if (supportCount || otherCount) {
    setHelpNote(
      "node-data-note",
      `${supportCount + otherCount} supplementary node dataset(s) attached.`,
      `Includes ${supportCount} supplementary support source(s) and ${otherCount} other metric source(s). Companion trees are matched by shared descendant taxon bipartitions regardless of root placement or sister-clade rotation; absent bipartitions display an en-dash (–).`,
    );
  } else {
    setHelpNote(
      "node-data-note",
      "Nodes matched automatically by shared taxon bipartitions.",
      "Companion trees are matched to primary-tree nodes by shared descendant taxon sets (unrooted bipartitions for support), regardless of sister-clade rotation or root placement; discordant bipartitions absent from a companion tree are shown as an en-dash (–).",
    );
  }
}

function createNodeDataSource(text, fileName, kind, preparedRoot = null, declaredScale = $("support-new-source-scale").value) {
  const parsedRoot = preparedRoot || parseNewick(text);
  PhyloRenderGenePreparation.assertRenderable(parsedRoot);
  const tipAlignment = buildTipKeyAlignment(parsedRoot, state.parsedRoot || state.root);
  const timeDiagnostics = treeTimeDiagnostics(parsedRoot);
  const fieldCatalog = discoverNodeNumericFields(parsedRoot);
  const autoSupportValues = buildNodeValueIndex(parsedRoot, "auto-support", tipAlignment.keyMap);
  const ageValues = timeDiagnostics.ultrametric ? buildNodeValueIndex(parsedRoot, "ages", tipAlignment.keyMap) : new Map();
  if (kind === "support" && !autoSupportValues.size && !fieldCatalog.some(field => field.scalar)) {
    throw new Error("No numeric internal node annotations suitable for branch support were found");
  }
  if (kind === "other" && !fieldCatalog.length && !ageValues.size) {
    throw new Error("No numeric internal node annotations found, and branch lengths are not ultrametric for computing node ages");
  }
  let extraction;
  if (kind === "support") {
    extraction = autoSupportValues.size
      ? "auto-support"
      : `field:${fieldCatalog.find(field => field.scalar).key}`;
  } else if (fieldCatalog.length) {
    const preferredKeys = ["height", "height_mean", "height_median", "label", "rate", "rate_mean"];
    const preferredField = preferredKeys.map(key => fieldCatalog.find(field => field.key === key)).find(Boolean) || fieldCatalog[0];
    extraction = `field:${preferredField.key}`;
  } else {
    extraction = "ages";
  }
  const source = {
    id: `data-${state.nextNodeDataSourceId++}`,
    kind,
    fileName,
    rawText: text,
    name: inferNodeDataName(fileName, kind, extraction),
    parsedRoot,
    tipKeyMap: tipAlignment.keyMap,
    tipAlignment,
    extraction,
    values: extraction === "ages" ? ageValues : buildNodeValueIndex(parsedRoot, extraction, tipAlignment.keyMap),
    fieldCatalog,
    autoSupportCount: autoSupportValues.size,
    ageEligible: timeDiagnostics.ultrametric,
    digits: 2,
    ...(kind === "support" ? {scale: declaredScale} : {}),
  };
  if (!matchedNodeValueCount(source)) throw new Error("Zero internal nodes matched the primary tree; verify taxon names and topology");
  return source;
}

async function importNodeDataFiles(fileList, kind) {
  if (!state.root) return showMessage("Import and render a primary tree first", true);
  const files = [...fileList];
  if (!files.length) return;
  return runTreeLoad("Attaching Supplementary Node Data", async progress => {
    const added = [], errors = [];
    for (const [index, file] of files.entries()) {
      await progress.stage(1, `Reading and matching file ${index + 1} / ${files.length}: ${file.name}`);
      try {
        const text = await readTreeFile(file);
        const source = createNodeDataSource(text, file.name, kind, await parseNewickAsync(text));
        if (kind === "support") mainSupportScales(source.values, source.scale);
        state.nodeDataSources.push(source);
        added.push(source);
      } catch (error) {
        checkScienceCancellation();
        errors.push(`${file.name}: ${error.message}`);
      }
    }
    if (added.length) {
      state.manualLabels.clear();
      await finishInteractiveTreeLoad(progress);
    } else if (errors.length) throw new Error(errors.join("; "));
    const addedText = added.length ? `Added ${added.length} ${kind === "support" ? "support" : "node metric"} tree file(s)` : "";
    showMessage([addedText, ...errors].filter(Boolean).join("; "), errors.length > 0 && !added.length);
  });
}

