function applyTipLabelOverrides(...args) { return sampleNamesWorkbench().applyOverrides(...args); }
function removeTipLabelOverride(...args) { return sampleNamesWorkbench().removeOverride(...args); }
function clearTipLabelOverrides(...args) { return sampleNamesWorkbench().clearOverrides(...args); }

