    svgEl, appendNodeLabelArrow, enableLabelDrag, refineReadableNodeLabelSteps, countResidualCollisions, updateLabelWarnings, horizontalLayoutForHeight, appendTipLabelContent, fitTipLabelWidth, composeTimeNodeAnnotation, buildCladeBarLayout, drawCladeBars, drawRetainedNodeLabels,
