async function dateCloudTrees(roots, rootAge, existingSpeciesAges = null) {
  if (!roots.length) return new Map();
  state.cloud.treePLRuns = [];
  const names = PhyloRenderCloud.sampleProfile(roots[0]).names;
  // Numerical normalization is confined to the solver request/output. Reference
  // ages, stored species nodes and exported units never change (e.g. yr vs Ma).
  const numericalScale = cloudTreePLNumericalScale(rootAge);
  async function runBatch(trees) {
    const result = await PhyloRenderNativeClient.run("treepl", {
      analysis_kind: "display_alignment", age: rootAge * numericalScale,
      trees: trees.map(tree => ({ ...tree,
        calibrations: tree.calibrations?.map(item => ({ ...item, age: item.age * numericalScale })) })),
    }, { signal: currentScienceSignal(), onProgress: message => { $("tree-loading-detail").textContent = message; } });
    if (result.engine !== "bundled-treePL" || result.datedTrees?.length !== trees.length) throw new Error("Incomplete output returned by the bundled treePL service");
    if (result.seed !== 1) throw new Error("Bundled treePL service did not apply deterministic seed = 1; restart the local backend service");
    state.cloud.treePLSeed = result.seed;
    state.cloud.treePLRuns.push({ engine: result.engine, analysis_kind: "display_alignment",
      binary_sha256: result.binary_sha256 || null, seed: result.seed,
      numsites: result.numsites ?? 100000000, numsites_is_synthetic: true,
      smooth: result.smooth ?? 100, numerical_scale: numericalScale,
      source_time_unit: cloudTimeUnit(), root_age: rootAge, tree_count: trees.length,
      constraints: result.constraints || trees.map(tree => ({ root_tips: tree.rootTips, shared_clades: tree.calibrations || [] })) });
    return result.datedTrees.map(text => {
      // Solver output is derived from already validated inputs. Rooting can
      // retain path-only old roots; do not misclassify these as uploaded data.
      const root = parseNewick(text, { validateInput: false });
      (function restoreUnits(node) {
        node.children.forEach(child => { child.length /= numericalScale; restoreUnits(child); });
      })(root);
      return root;
    });
  }
  const datedAges = new Map();
  const speciesRoot = roots[0];
  const speciesAges = existingSpeciesAges || PhyloRenderCloud.agesFromDatedTree(speciesRoot,
    (await runBatch([PhyloRenderCloud.treePLInput(speciesRoot, names)]))[0], names, rootAge);
  if (Math.abs(speciesAges.get(speciesRoot) - rootAge) > Math.max(.001, rootAge * .0001)) throw new Error("Calibrated species-tree root age does not match the configured root age");
  datedAges.set(speciesRoot, speciesAges);
  if (roots.length > 1) {
    const genes = roots.slice(1);
    const calibrations = genes.map(root => PhyloRenderCloud.sharedAgeCalibrations(speciesRoot, speciesAges, root, names));
    const inputs = genes.map((root, index) => {
      const { newick, rootTips } = PhyloRenderCloud.treePLInput(root, names);
      return { newick, rootTips, calibrations: calibrations[index].map(({ tips, age }) => ({ tips, age })) };
    });
    const datedTrees = [];
    for (let offset = 0; offset < inputs.length; offset += 100) {
      $("tree-loading-detail").textContent = `Running treePL alignment: gene trees ${offset + 1}–${Math.min(inputs.length, offset + 100)} / ${inputs.length}...`;
      datedTrees.push(...await runBatch(inputs.slice(offset, offset + 100)));
    }
    genes.forEach((root, index) => {
      const ages = PhyloRenderCloud.agesFromDatedTree(root, datedTrees[index], names, rootAge);
      PhyloRenderCloud.verifySharedAges(root, ages, calibrations[index], rootAge);
      datedAges.set(root, ages);
    });
  }
  return datedAges;
}

function cloudTreePLNumericalScale(rootAge) {
  if (!Number.isFinite(rootAge) || rootAge <= 0) throw new Error("Invalid species-tree root age");
  return rootAge > 1e6 || rootAge < .01 ? 10 / rootAge : 1;
}

