  const labelSource={taxonNameMatches:cloud.taxonNameMatches,taxonNameParses:cloud.taxonNameParses,taxonNameEngine:cloud.taxonNameEngine};
  const result=yield* cloudTreeRenderer().renderSteps({svg,model,options,timeBackground,timeFonts,rowStep,tips,layout:cloudLayout,
    unit:cloudTimeUnit(),fontFamily:figureSystemSansFamily(),cladeSelectionMode:state.cladeSelectionMode,labelSource,provenance});
  state.currentLayoutInfo={...result.layout,tipSpacingRoot:species};
  if(species)commitAutomaticTipSpacing(result.layout.tipSpacing);
  if(result.rangeCounts)updateCloudPieAgeRangeControls(result.rangeCounts);
  $("tip-count").textContent=String(result.tips);
