function updateCloudStatus() {
  const cloud = state.cloud, audit = cloud.geneAudit;
  updateCloudDatingControls();
  updateCloudLayerControls();
  const fourPartOption = $("cloud-pie-mode").querySelector('option[value="four"]');
  fourPartOption.disabled = Boolean(cloud.phyPartsTable && !cloud.phyPartsTable.detailed);
  if (fourPartOption.disabled && $("cloud-pie-mode").value === "four") $("cloud-pie-mode").value = "two";
  $("cloud-pie-composition-status").textContent = fourPartOption.disabled
    ? "Imported legacy table lacks top-conflict / other-conflict breakdown and supports two-part pies only. Re-upload raw gene trees or a full four-category node table."
    : cloud.phyPartsTable ? "Full four-category statistics stored; switching between two-part and four-part updates display without recalculating."
      : "All four bipartition categories are always computed; two-part vs. four-part controls display only.";
  const species = cloud.speciesRoot;
  const outgroup = species && PhyloRenderCloud.inferredOutgroup(species);
  const rootLengths = species?.children?.map(child => child.length);
  const rootStatus = species
    ? `Species tree preserves the input file root${outgroup ? ` (single-taxon outgroup: ${outgroup})` : ""} without rerooting. ${rootLengths?.length === 2 && rootLengths.every(length => length !== null && length !== undefined && Number(length) === 0) ? "Both basal root edges have zero length in the file; visual coordinates do not represent raw branch lengths." : "Displayed branch spans are ultrametrically aligned and do not represent raw substitution branch lengths."}`
    : "Preserves the input species-tree root; automatic rerooting is never applied.";
  $("cloud-root-status").textContent = `${rootStatus}${cloud.importedDating
    ? ` Preserved imported ages: root age ${cloud.datedRootAge} ${cloudTimeUnitLabel()} (${cloud.importedDating.ageSource}); treePL skipped for species tree.`
    : cloud.datingEngine === "relative-display"
    ? " treePL not executed: horizontal coordinates represent relative topological depth rather than divergence time."
    : cloud.datingEngine === "bundled-treePL" ? " Calibrated via bundled treePL; schematic root age is not fossil-calibrated." : ""}`;
  $("cloud-species-name").textContent = cloud.speciesName || "Not imported";
  $("cloud-genes-name").textContent = cloud.geneName || "Not imported";
  $("cloud-phyparts-name").textContent = cloud.phyPartsName || "Computed automatically upon gene-tree upload";
  $("cloud-phyparts-recalculate").disabled = !cloud.geneFile || cloud.phyPartsBusy;
  $("cloud-phyparts-download").disabled = !cloud.phyPartsText || cloud.phyPartsBusy;
  if ($("cloud-restore-hidden-pies")) $("cloud-restore-hidden-pies").hidden = !cloud.hiddenPieNodes.size;
  const speciesMethod = $("cloud-species-method").value;
  const genesMethod = $("cloud-genes-method").value;
  const showGene = $("cloud-show-gene").checked;
  $("cloud-validation").textContent = !showGene
    ? !speciesMethod ? "Select the species-tree input type; with the cloudogram hidden, species tree and discordance pies can be rendered independently."
      : !species ? "Import a species tree; gene trees are optional when rendering the species tree alone."
      : `Species tree loaded (${PhyloRenderCloud.tips(species).length} taxa); ready for discordance pies (${cloud.importedDating ? "preserving imported ages" : cloud.datingEngine === "relative-display" ? "relative layout" : "treePL display alignment"}).`
    : !["ml", "dated"].includes(speciesMethod)
      ? "Select an undated ML phylogram or a time-calibrated chronogram; raw ASTRAL coalescent branch lengths cannot be used for cloudogram alignment."
      : !species ? "Import a species tree of the selected type; calibrated ages are preserved without re-dating."
      : genesMethod !== "ml" ? "Species tree validated; confirm that gene trees were inferred by maximum likelihood (substitutions/site)."
      : audit
        ? `Parsed ${audit.total} gene trees: ${audit.accepted} complete-taxon ML trees, ${audit.mismatch} partial/mismatched taxon sets, ${audit.invalid} invalid. ${audit.firstRejected ? `First exclusion (tree #${audit.firstRejected.line}): ${audit.firstRejected.reason}` : ""}`
        : `Species tree loaded (${PhyloRenderCloud.tips(species).length} taxa); upload the ML gene-tree collection.`;
  const match = cloud.speciesRoot && cloud.phyPartsTable ? PhyloRenderCloud.matchPhyParts(cloud.speciesRoot, cloud.phyPartsTable) : null;
  $("cloud-phyparts-status").textContent = match
    ? `${cloud.phyPartsMeta ? `Built-in discordance analysis completed in ${cloud.phyPartsMeta.elapsedSeconds.toFixed(1)} s.` : "Precomputed node table loaded."} Evaluated ${cloud.phyPartsTable.sourceTotal ?? "per-node"} gene trees across ${match.matched.size} matched nodes.${audit?.stats ? ` Input ${audit.total}: ${audit.stats.accepted} comparable, ${audit.stats.unrootable} unrootable/missing outgroup, ${audit.stats.unknown} unmatched taxa, ${audit.invalid} invalid/duplicate. Cloudogram eligible: ${audit.accepted} complete ML trees (${cloud.geneRoots.length} overlaid).` : ""}`
    : "Computed automatically once species and gene trees are loaded; partial-taxon gene trees participate in discordance statistics while the cloudogram uses the complete-taxon ML subset.";
}

async function runAutomaticPhyParts(speciesRoot, genes, names, prepared) {
  prepared ||= await PhyloRenderInputTasks.run("payload", {speciesRoot,genes,names,
    options: {field: $("cloud-phyparts-field").value, scale: $("cloud-phyparts-scale").value,
      threshold: Number($("cloud-phyparts-threshold").value) / 100}}, {signal: currentScienceSignal()});
  const result = await PhyloRenderInputTasks.run("phyparts", prepared.payload, {
    signal: currentScienceSignal(), timeoutMs: 300000, onProgress: update => {
      $("tree-loading-detail").textContent = `Computing rooted bipartition discordance: ${update.current} / ${update.total}`;
    },
  });
  if (result?.engine !== "PhyloRender-conflict-statistics"
    || result.algorithm !== PhyloRenderPhyParts.ALGORITHM
    || result.geneCount !== genes.length || result.mode !== "four")
    throw new Error("Discordance engine provenance, version, four-category mode, or gene count mismatch");
  if (!PhyloRenderCloud.parsePhyPartsTable(result.table).detailed) throw new Error("Built-in discordance engine did not return full four-category counts");
  return { ...result, supportField: $("cloud-phyparts-field").value, supportScale: prepared.scale, supportUnitPolicy: prepared.support_unit_policy,
    rootPolicy: $("cloud-phyparts-root-policy").value };
}

async function importCloudGenes(file) {
  const previousCloud = structuredClone(state.cloud);
  try { return await importCloudGenesCandidate(file); }
  catch (error) {
    state.cloud = previousCloud; updateCloudStatus();
    if (state.workspaceMode === "cloud" && !currentScienceSignal()?.aborted) await renderTreeCooperatively();
    throw error;
  }
}

async function importCloudGenesCandidate(file) {
  if (!file || !state.cloud.speciesRoot) throw new Error("Import a species tree first");
  if (state.cloud.phyPartsBusy) throw new Error("Discordance analysis is already running; wait for completion");
  const cloud = state.cloud, text = await readTreeFile(file, true);
  const threshold = Number($("cloud-phyparts-threshold").value) / 100;
  if (!Number.isFinite(threshold) || threshold < 0 || threshold >= 1) throw new Error("Discordance support cutoff must be within 0–99.9%");
  const field = $("cloud-phyparts-field").value;
  const prepared = await PhyloRenderInputTasks.run("genes", {
    text, speciesRoot: cloud.speciesRoot, filename: file.name,
    rootPolicy: $("cloud-phyparts-root-policy").value,
    outgroups: $("cloud-phyparts-outgroups").value.split(/\r?\n/).map(name => name.trim()).filter(Boolean),
    canCloud: ["ml", "dated"].includes($("cloud-species-method").value) && $("cloud-genes-method").value === "ml",
    field, scale: $("cloud-phyparts-scale").value, threshold,
  }, { signal: currentScienceSignal(), onProgress: update => {
    $("tree-loading-detail").textContent = `Validating gene trees ${update.current} / ${update.total} (${update.accepted} comparable)...`;
  } });
  checkScienceCancellation();
  const {accepted,audit,names} = prepared;
  const statistics = {length: prepared.payload.genes.length};
  Object.assign(cloud, { geneFile: file, geneAudit: audit, geneName: file.name, geneRoots: [], phyPartsBusy: true });
  updateCloudStatus();
  try {
  const result = await runAutomaticPhyParts(cloud.speciesRoot, statistics, names, prepared);
  Object.assign(cloud, { phyPartsText: result.table, phyPartsTable: PhyloRenderCloud.parsePhyPartsTable(result.table),
    phyPartsName: "Built-in discordance analysis · all comparable gene trees", phyPartsMeta: result });
  let datingError = prepared.cloudLimitError;
  if (accepted.length && $("cloud-show-gene").checked) {
  $("tree-loading-detail").textContent = `Discordance statistics complete; aligning ${accepted.length} cloudogram gene trees to shared species-tree clades...`;
  const rootAge = cloudControls().age;
  const knownSpeciesAges = ["bundled-treePL", "imported-dated"].includes(cloud.datingEngine) && cloud.datedRootAge === rootAge
    ? cloud.datedAges.get(cloud.speciesRoot) : null;
  try {
    const datedAges = await dateCloudTrees([cloud.speciesRoot, ...accepted], rootAge, knownSpeciesAges);
    Object.assign(cloud, { geneRoots: accepted, datedAges, datedRootAge: rootAge,
      datingEngine: cloud.importedDating ? "imported-dated" : "bundled-treePL", geneDatingEngine: "bundled-treePL" });
  } catch (error) { checkScienceCancellation(); datingError = `Cloudogram treePL alignment incomplete: ${error.message}. Discordance statistics retained.`; }
  }
  cloud.datingError = datingError;
  audit.trees.forEach(row => { row.overlay_drawn = Boolean(row.cloud && cloud.geneRoots.length); });
  showMessage(`Evaluated ${statistics.length} / ${audit.total} comparable gene trees.${cloud.geneRoots.length ? ` Overlaid ${cloud.geneRoots.length} complete ML trees in cloudogram.` : " Cloudogram not overlaid; species tree and discordance pies ready."} ${datingError || ""}`.trim(), Boolean(datingError));
  } finally {
    cloud.phyPartsBusy = false; updateCloudStatus();
    if (state.workspaceMode === "cloud" && !currentScienceSignal()?.aborted) await renderTreeCooperatively();
  }
}

function renderConflictTree() { return finishRenderSteps(renderConflictTreeSteps()); }
