  const {groupColors,supportEntries,supportLayout,branchSegments,layout}=yield* conflictRenderer().renderSteps({
    svg,prepared,originalPrimary:state.conflict.nuclearRoot,
    groupAssignments:state.conflict.groupAssignments ? new Map(state.conflict.groupAssignments) : null,
    options,labelSource,
  });
  state.currentLayoutInfo=layout;
