  Object.assign(prepared,{groupColors,supportNodeCount:supportEntries.length,
    supportLabelCount:supportLayout.placed.length,supportCollisionCount:supportLayout.residualCollisions,
    supportLeaderWarningCount:supportLayout.leaderWarnings,supportMaximumLeaderLength:supportLayout.maximumLeaderLength});
  state.labelPlacements=supportLayout.placed.map(item=>({...item.rect,nodeId:item.node.id}));
  state.branchSegments=branchSegments;
  $("tip-count").textContent=prepared.comparison.sharedCount;
  $("support-count").textContent=supportEntries.length;
  $("collision-count").textContent=prepared.crossingsAfter;
  $("collision-count").classList.toggle("has-collisions",prepared.crossingsAfter>0);
