// Demonstration only: partition the built-in reference into complete,
// non-overlapping clades. Never call this for an uploaded species tree.
function seedDefaultCloudClades(root) {
  if (!root) return;
  const counts = new Map();
  function count(node) {
    const value = node.children.length ? node.children.reduce((sum, child) => sum + count(child), 0) : 1;
    counts.set(node, value);
    return value;
  }
  count(root);
  const partitions = [root];
  while (partitions.length < CLADE_PALETTE.length + 1) {
    const candidates = partitions.filter(node => node.children.length
      && partitions.length - 1 + node.children.length <= CLADE_PALETTE.length + 1);
    const largest = candidates.sort((a, b) => counts.get(b) - counts.get(a))[0];
    if (!largest) break;
    partitions.splice(partitions.indexOf(largest), 1, ...largest.children);
  }
  const order = new Map(PhyloRenderCloud.orderedTips(root, "small-top").map((tip, index) => [tip, index]));
  const groups = partitions.filter(node => counts.get(node) >= 3)
    .sort((a, b) => Math.min(...PhyloRenderCloud.tips(a).map(tip => order.get(tip)))
      - Math.min(...PhyloRenderCloud.tips(b).map(tip => order.get(tip))));
  groups.forEach((node, index) => {
    state.cloud.cladeColors.set(node.id, CLADE_PALETTE[index % CLADE_PALETTE.length]);
    state.cloud.cladeNames.set(node.id, `Group ${index + 1}`);
    state.cloud.cladeNameOrientations.set(node.id, PhyloRenderContract.cladeLabelOrientation.defaultValue);
  });
}

async function loadDefaultCloudWorkspace() {
  const example = globalThis.PhyloRenderLocalCloudExample;
  if (example && example.phyPartsMeta?.algorithm !== PhyloRenderPhyParts.ALGORITHM)
    throw Object.assign(new Error("Built-in cloudogram discordance snapshot version is outdated; recompute from raw gene trees."), { code: "PHYPARTS_CACHE_VERSION_MISMATCH" });
  await switchWorkspaceMode("cloud");
  clearCloudClades();
  return runTreeLoad("Loading demonstration Cloudogram", async progress => {
    if (!example) {
      await renderCloudTree();
      showMessage("Cloudogram & Discordance workspace ready. Import a species tree and gene-tree collection.");
      return;
    }
    await progress.stage(1, "Reading precomputed cloudogram demonstration...");
    if (example.version !== 1 || example.datingEngine !== "bundled-treePL")
      throw new Error("Invalid built-in cloudogram snapshot version or alignment engine.");
    const roots = example.trees.map(item => {
      const root = parseNewick(item.newick, { validateInput: false });
      const byClade = new Map(item.ages);
      const ages = new Map([...PhyloRenderCloud.nodeClades(root)].map(([node, clade]) => {
        const age = byClade.get(clade.key);
        if (!Number.isFinite(age) || age < 0) throw new Error("Built-in cloudogram snapshot is missing node ages.");
        return [node, age];
      }));
      PhyloRenderCloud.tips(root).forEach(tip => ages.set(tip, 0));
      if (Math.abs(ages.get(root) - example.rootAge) > .001)
        throw new Error("Inconsistent root age in built-in cloudogram snapshot.");
      return { root, ages };
    });
    if (!roots.length) throw new Error("Built-in cloudogram snapshot is empty.");
    $("cloud-species-method").value = "ml";
    $("cloud-genes-method").value = "ml";
    $("cloud-root-age").value = example.rootAge;
    $("cloud-root-age-unit").value = "relative";
    Object.assign(state.cloud, {
      speciesRoot: roots[0].root, speciesName: example.speciesName,
      geneRoots: roots.slice(1).map(item => item.root), geneName: example.geneName,
      geneAudit: example.geneAudit, geneFile: null,
      datedAges: new Map(roots.map(item => [item.root, item.ages])),
      datedRootAge: example.rootAge, datingEngine: example.datingEngine,
      importedDating: null, geneDatingEngine: "bundled-treePL",
      treePLSeed: null,
      phyPartsText: example.phyPartsText,
      phyPartsTable: PhyloRenderCloud.parsePhyPartsTable(example.phyPartsText),
      phyPartsName: "Built-in demo · precomputed discordance counts", phyPartsMeta: example.phyPartsMeta,
      hiddenPieNodes: new Set(),
      pieAgeRange: { minimum: null, maximum: null },
    });
    seedDefaultCloudClades(state.cloud.speciesRoot);
    resetCloudPieAgeRange();
    updateCloudStatus();
    renderTipLabelMappingControls();
    await progress.stage(5, "Rendering gene-tree cloud, species tree, and node discordance pies...");
    await document.fonts.ready;
    await renderCloudTree();
    fitTreeWidth();
    showMessage("Loaded demonstration cloudogram and display clades (uncalibrated relative scale). Uploading new data replaces this demo cleanly.");
  });
}

